import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷四·1","description":"易小帖 - 卷四·1","frontmatter":{"title":"卷四·1","description":"易小帖 - 卷四·1"},"headers":[],"relativePath":"classics/yixiaotie/095.md","filePath":"classics/yixiaotie/095.md"}'),o={name:"classics/yixiaotie/095.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷四·1",tabindex:"-1"},[r("卷四·1 "),e("a",{class:"header-anchor",href:"#卷四·1","aria-label":"Permalink to “卷四·1”"},"​")],-1),e("p",null,"蠱彖「先甲三日，後甲三日」馬融謂：「甲在東方，其先三日為東北之艮，後三日為東南之巽。」蠱之以艮巽成卦，可謂巧合矣。但以日作卦，以一卦作三日，俱無解處。且於巽五「先庚三日，後庚三日」不能相通。及胡雲峰襲其說，謂：「先天圖離在東主甲，由離而震而坤，越三卦而得艮，謂之先三日。由離而兌而乾，越三卦而得巽，謂之後三日。離者日也。」此襲馬氏說，而補救之。然何所謂先天圖？以文王作易而能據陳摶偽造之圖以為辭？此笑話也。且蠱之為卦，以艮巽耳。巽上下皆巽，而先兌三位，為坤後兌三位為坎。先庚三日後庚三日，其於坤坎何取焉？至來知德又襲兩家說，以蠱合艮巽，取易原圖為說，與馬氏同，而略顛倒之，以下巽為先甲，上艮為後甲，藉以明異。而於巽之先庚後庚則又取先天圓圖為說，謂艮巽夾兌，於西之中則錯亂極矣。先天不當與易本圖兩相錯舉，且巽只是巽而主兌而夾以巽，且復加艮，展轉無理。來易之襲舊儒說，而每多不合有如此。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
